Azure/Mount_file_share.content:
#!/bin/bash

# Configuration variables (these should be set in a separate config file or environment variables)
STORAGE_ACCOUNT_NAME=&quot;${STORAGE_ACCOUNT_NAME:-your_storage_account_name}&quot;
STORAGE_ACCOUNT_PASS=&quot;${STORAGE_ACCOUNT_PASS:-your_storage_account_key}&quot;
STORAGE_SHARE_URI=&quot;devsftppocunmanageddisk.file.core.windows.net/sftp&quot;
STORAGE_ACCOUNT_MOUNTPOINT=&quot;/mnt/$STORAGE_ACCOUNT_NAME&quot;
STORAGE_CREDENCIAL_FILE=&quot;/etc/$STORAGE_ACCOUNT_NAME.cred&quot;

# Function to display usage
usage() {
    echo &quot;Usage: $0 {mount|unmount|cleanup}&quot;
    echo &quot;  mount   : Mount the Azure file share&quot;
    echo &quot;  unmount : Unmount the Azure file share&quot;
    echo &quot;  cleanup : Remove credentials and fstab entry&quot;
    exit 1
}

# Function to check if running as root
check_root() {
    if [ &quot;$EUID&quot; -ne 0 ]; then
        echo &quot;Error: This script must be run as root.&quot;
        exit 1
    fi
}

# Function to validate required variables
validate_vars() {
    if [ -z &quot;$STORAGE_ACCOUNT_NAME&quot; ] || [ -z &quot;$STORAGE_ACCOUNT_PASS&quot; ]; then
        echo &quot;Error: STORAGE_ACCOUNT_NAME and STORAGE_ACCOUNT_PASS must be set.&quot;
        echo &quot;Set them as environment variables or edit the script.&quot;
        exit 1
    fi
}

# Function to create credentials file
create_credentials() {
    echo &quot;Creating credentials file at $STORAGE_CREDENCIAL_FILE...&quot;
    echo -e &quot;username=$STORAGE_ACCOUNT_NAME\npassword=$STORAGE_ACCOUNT_PASS&quot; &gt; &quot;$STORAGE_CREDENCIAL_FILE&quot;
    if [ $? -ne 0 ]; then
        echo &quot;Error: Failed to create credentials file.&quot;
        exit 1
    fi
    chmod 600 &quot;$STORAGE_CREDENCIAL_FILE&quot;
    echo &quot;Credentials file created and permissions set.&quot;
}

# Function to add fstab entry
add_fstab_entry() {
    # Check if entry already exists in /etc/fstab
    if grep -q &quot;$STORAGE_SHARE_URI&quot; /etc/fstab; then
        echo &quot;fstab entry already exists for $STORAGE_SHARE_URI.&quot;
        return 0
    fi

    echo &quot;Adding fstab entry for $STORAGE_SHARE_URI...&quot;
    echo &quot;//$STORAGE_SHARE_URI $STORAGE_ACCOUNT_MOUNTPOINT cifs nofail,vers=3.0,credentials=$STORAGE_CREDENCIAL_FILE,dir_mode=0777,file_mode=0777,serverino&quot; &gt;&gt; /etc/fstab
    if [ $? -ne 0 ]; then
        echo &quot;Error: Failed to add fstab entry.&quot;
        exit 1
    fi
    echo &quot;fstab entry added.&quot;
}

# Function to create mount point
create_mountpoint() {
    if [ ! -d &quot;$STORAGE_ACCOUNT_MOUNTPOINT&quot; ]; then
        echo &quot;Creating mount point at $STORAGE_ACCOUNT_MOUNTPOINT...&quot;
        mkdir -p &quot;$STORAGE_ACCOUNT_MOUNTPOINT&quot;
        if [ $? -ne 0 ]; then
            echo &quot;Error: Failed to create mount point.&quot;
            exit 1
        fi
        echo &quot;Mount point created.&quot;
    else
        echo &quot;Mount point $STORAGE_ACCOUNT_MOUNTPOINT already exists.&quot;
    fi
}

# Function to mount the file share
mount_fileshare() {
    # Check if already mounted
    if mountpoint -q &quot;$STORAGE_ACCOUNT_MOUNTPOINT&quot;; then
        echo &quot;File share is already mounted at $STORAGE_ACCOUNT_MOUNTPOINT.&quot;
        return 0
    fi

    echo &quot;Mounting file share at $STORAGE_ACCOUNT_MOUNTPOINT...&quot;
    mount -t cifs &quot;//$STORAGE_SHARE_URI&quot; &quot;$STORAGE_ACCOUNT_MOUNTPOINT&quot; -o vers=3.0,credentials=&quot;$STORAGE_CREDENCIAL_FILE&quot;,dir_mode=0777,file_mode=0777,serverino
    if [ $? -ne 0 ]; then
        echo &quot;Error: Failed to mount file share.&quot;
        exit 1
    fi
    echo &quot;File share mounted successfully.&quot;
}

# Function to unmount the file share
unmount_fileshare() {
    if ! mountpoint -q &quot;$STORAGE_ACCOUNT_MOUNTPOINT&quot;; then
        echo &quot;File share is not mounted at $STORAGE_ACCOUNT_MOUNTPOINT.&quot;
        return 0
    fi

    echo &quot;Unmounting file share from $STORAGE_ACCOUNT_MOUNTPOINT...&quot;
    umount &quot;$STORAGE_ACCOUNT_MOUNTPOINT&quot;
    if [ $? -ne 0 ]; then
        echo &quot;Error: Failed to unmount file share.&quot;
        exit 1
    fi
    echo &quot;File share unmounted successfully.&quot;
}

# Function to clean up (remove credentials and fstab entry)
cleanup() {
    echo &quot;Cleaning up configuration...&quot;

    # Unmount if mounted
    unmount_fileshare

    # Remove credentials file
    if [ -f &quot;$STORAGE_CREDENCIAL_FILE&quot; ]; then
        echo &quot;Removing credentials file $STORAGE_CREDENCIAL_FILE...&quot;
        rm -f &quot;$STORAGE_CREDENCIAL_FILE&quot;
        if [ $? -ne 0 ]; then
            echo &quot;Error: Failed to remove credentials file.&quot;
            exit 1
        fi
        echo &quot;Credentials file removed.&quot;
    fi

    # Remove fstab entry
    if grep -q &quot;$STORAGE_SHARE_URI&quot; /etc/fstab; then
        echo &quot;Removing fstab entry for $STORAGE_SHARE_URI...&quot;
        sed -i &quot;\|$STORAGE_SHARE_URI|d&quot; /etc/fstab
        if [ $? -ne 0 ]; then
            echo &quot;Error: Failed to remove fstab entry.&quot;
            exit 1
        fi
        echo &quot;fstab entry removed.&quot;
    fi

    # Remove mount point if empty
    if [ -d &quot;$STORAGE_ACCOUNT_MOUNTPOINT&quot; ]; then
        rmdir &quot;$STORAGE_ACCOUNT_MOUNTPOINT&quot; 2&gt;/dev/null
        if [ $? -eq 0 ]; then
            echo &quot;Mount point $STORAGE_ACCOUNT_MOUNTPOINT removed.&quot;
        else
            echo &quot;Mount point $STORAGE_ACCOUNT_MOUNTPOINT not removed (directory not empty or error occurred).&quot;
        fi
    fi

    echo &quot;Cleanup completed.&quot;
}

# Main logic
if [ $# -ne 1 ]; then
    usage
fi

check_root
validate_vars

case &quot;$1&quot; in
    mount)
        create_credentials
        create_mountpoint
        add_fstab_entry
        mount_fileshare
        ;;
    unmount)
        unmount_fileshare
        ;;
    cleanup)
        cleanup
        ;;
    *)
        usage
        ;;
esac

exit 0

Azure/PrivisionandorecursosnaAWSapartird.content:
Para o cenário em que uma VM do Azure executará pipelines do Azure DevOps e provisionará recursos no AWS, é crucial estabelecer uma autenticação segura e contínua. Aqui estão os melhores métodos para o conseguir:
OpenID Connect (OIDC)
O Azure DevOps pode ser integrado ao AWS por meio de um provedor de identidade OIDC, que permite que a VM do Azure assuma funções no AWS com segurança sem exigir chaves de acesso de longo prazo.
Como funciona:

Configure um fornecedor de identidade OIDC no AWS para a sua organização Azure Active Diretory (AAD) ou Azure DevOps.
Crie uma função IAM no AWS que confie no provedor OIDC e conceda as permissões necessárias.
Use aws sts assume-role-with-web-identity dentro do pipeline do Azure DevOps para obter credenciais temporárias.

Etapas
Aqui está uma visão geral dos recursos a serem criados no Terraform:
a) Provedor de Identidade OIDC
resource &quot;aws_iam_openid_connect_provider&quot; &quot;oidc_provider&quot; {
  client_id_list  = [&quot;sts.amazonaws.com&quot;]
  thumbprint_list = [&quot;&lt;THUMBPRINT_DO_OIDC&gt;&quot;] # Obtenha o thumbprint do emissor
  url             = &quot;vstoken.azure.net/&lt;ORGANIZATION&gt;&quot; # URL do emissor do Azure DevOps
}

b) Função IAM
resource &quot;aws_iam_role&quot; &quot;azure_devops_role&quot; {
  name = &quot;AzureDevOpsOIDCRole&quot;

  assume_role_policy = jsonencode({
    Version = &quot;2012-10-17&quot;
    Statement = [
      {
        Effect = &quot;Allow&quot;
        Principal = {
          Federated = aws_iam_openid_connect_provider.oidc_provider.arn
        }
        Action = &quot;sts:AssumeRoleWithWebIdentity&quot;
        Condition = {
          StringEquals = {
            &quot;vstoken.azure.net/&lt;ORGANIZATION&gt;:sub&quot; = &quot;system:serviceaccount:&lt;NAMESPACE&gt;:&lt;SERVICE_ACCOUNT&gt;&quot;
          }
        }
      }
    ]
  })
}

resource &quot;aws_iam_policy&quot; &quot;devops_policy&quot; {
  name        = &quot;AzureDevOpsPolicy&quot;
  description = &quot;Policy for Azure DevOps integration&quot;

  policy = jsonencode({
    Version = &quot;2012-10-17&quot;
    Statement = [
      {
        Effect   = &quot;Allow&quot;
        Action   = [&quot;s3:ListBucket&quot;, &quot;s3:GetObject&quot;]
        Resource = [&quot;arn:aws:s3:::&lt;YOUR_BUCKET&gt;/*&quot;]
      }
    ]
  })
}

resource &quot;aws_iam_role_policy_attachment&quot; &quot;attach_policy&quot; {
  role       = aws_iam_role.azure_devops_role.name
  policy_arn = aws_iam_policy.devops_policy.arn
}

c) Configuração do Pipeline
No Azure DevOps, configure o pipeline para usar a função IAM com o seguinte comando:
steps:
- script: |
    export AWS_ROLE_ARN=arn:aws:iam::&lt;AWS_ACCOUNT_ID&gt;:role/AzureDevOpsOIDCRole
    export AWS_WEB_IDENTITY_TOKEN_FILE=/path/to/oidc/token
    aws sts assume-role-with-web-identity \
      --role-arn $AWS_ROLE_ARN \
      --role-session-name DevOpsSession \
      --web-identity-token file://$AWS_WEB_IDENTITY_TOKEN_FILE
  displayName: &#039;Assume AWS Role&#039;

Vantagens

Não é necessário gerir chaves de acesso AWS a longo prazo.
Seguro e segue as práticas recomendadas, aproveitando tokens de curta duração.
Mais fácil de auditar e revogar o acesso, se necessário.

Quando usar
Melhor quando os seus pipelines de DevOps do Azure precisam de aprovisionar recursos do AWS de forma intermitente
ROLE_ARN=&quot;arn:aws:iam::********:role/AzureDevOpsOIDCRole&quot;
AUDIENCE=&quot;api://azure-awsoidcconnection&quot;


access_token=$(curl &quot;http://169.254.169.254/metadata/identity/oauth2/token?api-version=2018-02-01&amp;resource=${AUDIENCE}&quot; -H &quot;Metadata:true&quot; -s| jq -r &#039;.access_token&#039;)


credentials=$(aws sts assume-role-with-web-identity --role-arn ${ROLE_ARN} --web-identity-token ${access_token} --role-session-name AWSAssumeRole | jq &#039;.Credentials&#039; | jq &#039;.Version=1&#039;)

export AWS_ACCESS_KEY_ID=$(echo &quot;$credentials&quot; | jq -r &#039;.AccessKeyId&#039;)
export AWS_SECRET_ACCESS_KEY=$(echo &quot;$credentials&quot; | jq -r &#039;.SecretAccessKey&#039;)
export AWS_SESSION_TOKEN=$(echo &quot;$credentials&quot; | jq -r &#039;.SessionToken&#039;)

aws sts assume-role-with-web-identity --role-arn ${ROLE_ARN} --web-identity-token ${access_token} --role-session-name AWSAssumeRole

aws s3api create-bucket --bucket &quot;polattovmtestcli&quot; --region us-west-1 --create-bucket-configuration LocationConstraint=us-west-1

aws s3api delete-bucket --bucket &quot;polattovmtestcli&quot; --region us-east-1

Contas de serviço (IRSA)
As VMs do Azure dão suporte à Identidade Gerenciada, que pode ser vinculada às funções do AWS IAM usando a integração entre nuvens.
Como funciona:

Configure uma Identidade Gerenciada no Azure para sua VM.
Estabeleça uma relação de confiança entre a identidade gerenciada do Azure e a função do AWS IAM.
Use um serviço de federação como o Azure AD ou uma configuração de federação personalizada.
Crie uma função de IAM no AWS com política de confiança para aceitar tokens de identidade do Azure AD.
Configurar o pipeline para usar a identidade gerenciada para assumir a função do AWS IAM.

Vantagens:

Gerenciamento de credenciais simplificado por meio do Azure Managed Identity.
Credenciais de curta duração para segurança.
Totalmente integrado aos ecossistemas do Azure e do AWS.

Quando usar:
Ideal para cenários em que a VM do Azure é uma entidade de longa duração e serve como um hub central para CI/CD.
CLI do AWS com Azure Key Vault
Usando a CLI do AWS com chaves de acesso armazenadas no Azure Key Vault (como uma solução híbrida ou de backup). Para situações em que o OIDC ou o Managed Identity não é viável, pode utilizar chaves de acesso de forma segura.
Como funciona:

Armazene a chave de acesso e o segredo do AWS no Azure Key Vault.
Use pipelines do Azure DevOps para recuperar essas credenciais em tempo de execução.
Configure o AWS CLI ou SDK na VM do Azure com as credenciais recuperadas.

Vantagens:

Fácil de implementar e funciona em várias ferramentas de CI/CD.
Gerenciamento centralizado de segredos.

Desvantagens:

As credenciais de longo prazo aumentam o risco de uso indevido.
É necessário mais esforço para girar as chaves periodicamente.

Quando usar:
Como uma opção de recurso quando as funções de IAM com OIDC ou Identidade gerenciada não são viáveis.
Usar uma função entre contas com tokens temporários
Se a VM do Azure tiver um IP fixo ou uma ligação de rede privada, pode ser utilizada a assunção de funções do AWS através de uma troca segura de tokens.
Como funciona:

Use uma ID externa e uma relação de confiança entre o Azure DevOps e a função do AWS IAM.
O pipeline solicita credenciais temporárias por meio do processo de assunção de função.

Vantagens:

Forte controlo de acesso baseado em funções.
Seguro contra uso indevido.

Quando usar:
Adequado para ambientes altamente restritos com rede fixa
Recomendação
Para a maioria dos casos de utilização, as funções IAM do AWS com o fornecedor OIDC são a melhor opção devido à sua segurança, escalabilidade e facilidade de utilização. Se necessitar de uma integração mais estreita com o Azure, considere a utilização do Managed Identity com AWS IAM Roles.
Certifique-se de que a função do AWS IAM tem o princípio do menor privilégio, concedendo apenas as permissões necessárias para o provisionamento de recursos. Audite regularmente as políticas de acesso e monitorize os registos de pipeline para garantir a segurança e a conformidade.

Azure/scale_aks.content:
#!/bin/bash

RESOURCE_GROUP=&quot;&quot;
CLUSTER_NAME=&quot;&quot;
NODE_POOL_NAME=&quot;monitoring&quot;
CHECK_INTERVAL=300
DESIRED_COUNT=1


echo &quot;Starting node count monitoring for node pool &#039;$NODE_POOL_NAME&#039; in cluster &#039;$CLUSTER_NAME&#039;...&quot;

# Infinite loop to check node count every 5 minutes
while true; do

    NODE_COUNT=$(az aks nodepool show \
     --subscription &lt;subscription-id&gt; \
     --resource-group &quot;$RESOURCE_GROUP&quot; \
     --cluster-name &quot;$CLUSTER_NAME&quot; \
     --name &quot;$NODE_POOL_NAME&quot; \
     --query &quot;count&quot; \
     -o tsv 2&gt;/dev/null)

    if [ $? -ne 0 ]; then
        echo &quot;$(date): Error retrieving node count for &#039;$NODE_POOL_NAME&#039;. Check configuration.&quot;
        sleep &quot;$CHECK_INTERVAL&quot;
        continue
    fi

    echo &quot;$(date): Current node count for &#039;$NODE_POOL_NAME&#039; is $NODE_COUNT.&quot;

    if [ &quot;$NODE_COUNT&quot; -eq 0 ]; then
        echo &quot;$(date): Node count is 0. Scaling to $DESIRED_COUNT node(s)...&quot;
        az aks nodepool scale \
          --subscription &lt;subscription-id&gt; \
          --resource-group &quot;$RESOURCE_GROUP&quot; \
          --cluster-name &quot;$CLUSTER_NAME&quot; \
          --name &quot;$NODE_POOL_NAME&quot; \
          --node-count &quot;$DESIRED_COUNT&quot; \
          --no-wait

        if [ $? -eq 0 ]; then
            echo &quot;$(date): Scale command issued successfully.&quot;
        else
            echo &quot;$(date): Error scaling node pool &#039;$NODE_POOL_NAME&#039;.&quot;
        fi
    fi

    sleep &quot;$CHECK_INTERVAL&quot;
done

Elastic/Logstash/logstash_docker_basic_c.content:
O Logstash é uma ferramenta de processamento de dados que pode ser usada para coletar, transformar e enviar dados para o Elasticsearch. Configurar o Logstash no Docker é uma maneira eficiente de gerenciar sua infraestrutura de processamento de dados. Aqui está um guia básico para configurar o Logstash no Docker:
Estrutura de pasta
Primeiro, crie uma estrutura de pasta para organizar seus arquivos de configuração do Logstash:
logstash-docker
    ├── config
    │   ├── GeoLite2-City.mmdb # Opcional: banco de dados de geolocalização
    │   ├── logstash.yml # Configurações principais do Logstash
    │   └── pipelines.yml # Configurações de pipelines do Logstash
    ├── pipeline
    │   ├── index_mapping.tpl # Opcional: template de mapeamento para índices do Elasticsearch
    │   └── logs.conf # Pipeline do Logstash
    ├── docker-compose.yml
Configuração do Logstash
logstash-docker/config/logstash.yml
Configure as opções básicas do Logstash, como host, porta, formato de log e monitoramento:
http.host: 0.0.0.0
http.port: 9600
log.format: json
log.level: info
xpack.monitoring.enabled: false
logstash-docker/config/pipelines.yml
O logstash pode ter múltiplos pipelines. Aqui, definimos um pipeline chamado “main” que aponta para a pasta onde os arquivos de configuração do pipeline estão localizados:
- pipeline.id: main
  path.config: /usr/share/logstash/pipeline
Para mais informações sobre as opções de configuração, consulte a documentação oficial do Logstash.
logstash-docker/pipeline/logs.conf
Este é um exemplo básico de configuração de pipeline do Logstash.
input {
    kafka {
        bootstrap_servers =&gt; &quot;${KAFKA_BOOTSTRAP_SERVERS}&quot;
        topics =&gt; [ &quot;${KAFKA_TOPIC}&quot; ]
        security_protocol =&gt; &quot;SASL_SSL&quot;
        sasl_mechanism =&gt; &quot;SCRAM-SHA-512&quot;
        sasl_jaas_config =&gt; &#039;org.apache.kafka.common.security.scram.ScramLoginModule required username=&quot;${KAFKA_USER}&quot; password=&quot;${KAFKA_USER_PASSWORD}&quot;;&#039;
        auto_offset_reset =&gt; &quot;earliest&quot;
        consumer_threads =&gt; &quot;${KAFKA_CONSUMER_THREADS}&quot;
        group_id =&gt; &quot;${GROUP_ID}&quot;
    }
}

filter {
  json { source =&gt; &quot;message&quot; }

  mutate {
    remove_field =&gt; [
      &quot;event&quot;, &quot;agent&quot;, &quot;host&quot;,
      &quot;docker&quot;, &quot;log&quot;, &quot;[container][labels]&quot;, &quot;@timestamp&quot;,
      &quot;@version&quot;, &quot;ecs&quot;, &quot;input&quot;,
      &quot;stream&quot;
    ]
  }

  date {
    match =&gt; [ &quot;[data][time_iso8601]&quot;, &quot;ISO8601&quot; ]
  }

  mutate {
    add_field =&gt; {
      &quot;[@metadata][IndexName]&quot; =&gt; &quot;%{[vmss_name]}&quot;
    }
  }

  cidr {
    address =&gt; [ &quot;%{[data][remote_addr]}&quot; ]
    network =&gt; [ &quot;10.0.2.0/27&quot; ]
    add_field =&gt; { &quot;cidr&quot; =&gt; &quot;privateIP&quot; }
  }  

  # Opcional: Se o endereço IP não for privado, adicione informações de geolocalização usando o banco de dados GeoLite2. Certifique-se de ter o arquivo GeoLite2-City.mmdb na pasta de configuração do Logstash.
  if &quot;privateIP&quot; not in [cidr] {
    geoip {
      source =&gt; &quot;[data][remote_addr]&quot;
      database =&gt; &quot;/usr/share/logstash/config/GeoLite2-City.mmdb&quot;
      target =&gt; &quot;geoip&quot;
      remove_field =&gt; [
        &quot;[geoip][continent_code]&quot;, &quot;[geoip][timezone]&quot;, &quot;[geoip][postal_code]&quot;,
        &quot;[geoip][country_code3]&quot;, &quot;[geoip][country_name]&quot;, &quot;[geoip][ip]&quot;,
        &quot;[geoip][coordinates]&quot;, &quot;[geoip][dma_code]&quot;
      ]
    }
  }

  mutate {
    remove_field =&gt; [ &quot;cidr&quot; ]
  }
}

output {
  elasticsearch {
    hosts =&gt; [ &quot;${ELASTIC_HOSTS}&quot; ]
    index =&gt; &quot;%{[@metadata][IndexName]}-%{+YYYY.MM}&quot;
    user =&gt; &quot;${ELASTIC_USER}&quot;
    password =&gt; &quot;${ELASTIC_PASSWORD}&quot;
  }

  # Utilizado para debug, pode ser removido em produção. Ajuda a visualizar os dados que chegando no Logstash.
  stdout {
    codec =&gt; rubydebug {
      metadata =&gt; true
    }
  }
}
Configuração do Docker Compose
logstash-docker/docker-compose.yml
services:
  setup:
    image: docker.elastic.co/logstash/logstash:8.11.0
    command: &gt;
      bash -c &#039;
        if [ -z &quot;$ELASTIC_USER&quot; ]; then
          echo &quot;Set the ELASTIC_USER environment variable in the .env file&quot;;
          exit 1;
        elif [ -z &quot;$ELASTIC_PASSWORD&quot; ]; then
          echo &quot;Set the ELASTIC_PASSWORD environment variable in the .env file&quot;;
          exit 1;
        elif [ -z &quot;$ELASTIC_HOSTS&quot; ]; then
          echo &quot;Set the ELASTIC_HOSTS environment variable in the .env file&quot;;
          exit 1;
        else
          echo &quot;All required environment variables are set. Starting Logstash...&quot;;
          exit 0;
        fi
      &#039;
    env_file:
      - ./.env
  logstash:
    image: docker.elastic.co/logstash/logstash:8.11.0
    ports:
      - &quot;5044:5044&quot;
      - &quot;9600:9600&quot;
    env_file:
      - ./.env
    volumes:
      - ./config:/usr/share/logstash/config
      - ./pipeline/logs.conf:/usr/share/logstash/pipeline/logs.conf
    depends_on:
      - setup
Variáveis de ambiente
logstash-docker/.env
export KAFKA_BOOTSTRAP_SERVERS=&quot;b-1-public:9196,b-2-public:9196&quot;
export KAFKA_TOPIC_REDSYS=&quot;&quot;
export KAFKA_USER=&quot;&quot;
export KAFKA_USER_PASSWORD=&quot;&quot;
export KAFKA_CONSUMER_THREADS=&quot;3&quot;
export GROUP_ID=&quot;&quot;
export ELASTIC_HOSTS=&quot;&quot;
export ELASTIC_USER=&quot;&quot;
export ELASTIC_PASSWORD=&quot;&quot;
export LS_JAVA_OPTS=&quot;-Xms1g -Xmx2g&quot;

Elastic/Logstash/recuperando_logs_do_s3.content:
Introdução
Neste guia, vamos aprender como configurar o Logstash para recuperar logs armazenados no Amazon S3 e indexá-los no Elasticsearch. O Logstash é uma ferramenta poderosa para coletar, processar e transformar dados antes de enviá-los para o Elasticsearch.
Pré-requisitos
Antes de começar, certifique-se de ter:

Uma conta na AWS com acesso ao S3.
O Logstash instalado em sua máquina (Para roda em docker, leia Básico de Configuração do Logstash no Docker).
O Elasticsearch configurado e em execução.

Passo a passo completo


Crie o arquivo de configuração do Logstash.
mkdir -p ~/s3_logs_recovery
touch ~/s3_logs_recovery/pipeline.conf


Crie o arquivo logs.conf com a seguinte configuração:
input {
 s3 {
   access_key_id =&gt; &quot;${AWS_ACCESS_KEY_ID}&quot;
   secret_access_key =&gt; &quot;${AWS_SECRET_ACCESS_KEY}&quot;
   role_arn =&gt; &quot;${AWS_ROLE_ARN}&quot;                     # Se usar role assume, priorize isso (mais seguro)
   bucket =&gt; &quot;${AWS_BUCKET_NAME}&quot;
   region =&gt; &quot;${AWS_REGION}&quot;
   prefix =&gt; &quot;${AWS_BUCKET_PREFIX}&quot;                  # Ex: &quot;logstash/2026/01/19/&quot; para um dia específico
   codec =&gt; &quot;json_lines&quot;                             # Perfeito se forem arquivos .json com um evento por linha
   temporary_directory =&gt; &quot;/tmp/logstash/&quot;
   interval =&gt; 30                                    # Tempo entre polls (segundos)
   watch_for_new_files =&gt; false                      # false = processa tudo uma vez e para (ideal para backfill histórico)
   delete =&gt; false                                   # NÃO deleta nada do S3
   sincedb_path =&gt; &quot;/var/lib/logstash/sincedb_s3&quot;    # Persista esse arquivo em volume Docker para evitar reprocessar
   additional_settings =&gt; {
       &quot;force_path_style&quot; =&gt; false                     # Útil se bucket for path-style (raro hoje)
   }
 }
}

filter {
# Adicione aqui se precisar parsear/extraír campos dos JSONs
# Exemplo: json { source =&gt; &quot;message&quot; target =&gt; &quot;parsed&quot; } se não for json_lines
}

output {
   elasticsearch {
     hosts =&gt; [ &quot;${ELASTIC_HOSTS}&quot; ]                   # Verifique se é &quot;htstp://elasticsearch:9200&quot; ou URL completa
     index =&gt; &quot;logs-%{+YYYY.MM.dd}&quot;                     # Nome do índice, pode usar data para rotação
     user =&gt; &quot;${ELASTIC_USER}&quot;
     password =&gt; &quot;${ELASTIC_PASSWORD}&quot;
     document_id =&gt; &quot;%{EventUUID}&quot; # Se seus eventos tiverem um campo único, use aqui para evitar duplicatas
   }

# Para debug, envie também para o console (opcional)
stdout {
 codec =&gt; rubydebug {
   metadata =&gt; true
 }
}
}
Defina também as configurações de Logstash no diretório config (opcional, mas recomendado para organização):
mkdir -p ~/s3_logs_recovery/config
touch ~/s3_logs_recovery/config/logstash.yml
Exemplo de logstash.yml:
http.host: 0.0.0.0
http.port: 9600
log.format: json
log.level: info
xpack.monitoring.enabled: false
Exemplo de config de pipeline (opcional, se quiser separar pipelines):
- pipeline.id: main
  path.config: /usr/share/logstash/pipeline


Crie o arquivo .env para armazenar suas variáveis de ambiente sensíveis.
touch ~/s3_logs_recovery/.env
Adicione as seguintes variáveis ao arquivo .env:
AWS_ACCESS_KEY_ID=your_access_key_id
AWS_SECRET_ACCESS_KEY=your_secret_access_key
AWS_ROLE_ARN=arn:aws:iam::123456789012:role/your_role_name  # Se usar role assume, caso contrário deixe em branco
AWS_BUCKET_NAME=your_bucket_name
AWS_REGION=your_bucket_region
AWS_BUCKET_PREFIX=optional_prefix_in_bucket/  # Ex: &quot;logstash/2026/01/19/&quot;
ELASTIC_HOSTS=http://elasticsearch:9200  # Ou URL completa do seu Elasticsearch
ELASTIC_USER=your_elastic_user
ELASTIC_PASSWORD=your_elastic_password
LS_JAVA_OPTS=&quot;-Xms1g -Xmx2g&quot;


Crie o docker-compose para rodar o Logstash.
touch ~/s3_logs_recovery/docker-compose.yml
services:
  setup:
    image: docker.elastic.co/logstash/logstash:8.11.0
    command: &gt;
      bash -c &#039;
        if [ -z &quot;$ELASTIC_USER&quot; ]; then
          echo &quot;Set the ELASTIC_USER environment variable in the .env file&quot;;
          exit 1;
        elif [ -z &quot;$ELASTIC_PASSWORD&quot; ]; then
          echo &quot;Set the ELASTIC_PASSWORD environment variable in the .env file&quot;;
          exit 1;
        elif [ -z &quot;$ELASTIC_HOSTS&quot; ]; then
          echo &quot;Set the ELASTIC_HOSTS environment variable in the .env file&quot;;
          exit 1;
        else
          echo &quot;All required environment variables are set. Starting Logstash...&quot;;
          exit 0;
        fi
      &#039;
    env_file:
      - ./.env
  logstash:
    image: docker.elastic.co/logstash/logstash:8.11.0
    ports:
      - &quot;5044:5044&quot;
      - &quot;9600:9600&quot;
    env_file:
      - ./.env
    volumes:
      - ./logs.conf:/usr/share/logstash/pipeline/logs.conf
      - ./config:/usr/share/logstash/config
      - ./sincedb:/var/lib/logstash  # pasta local persistente para sincedb
    depends_on:
      - setup


Rode o Logstash usando o docker-compose.
docker-compose up


Estrutura do projeto:
s3_logs_recovery/
├── .env
├── docker-compose.yml
├── logs.conf
├── config/
│   └── logstash.yml
│   └── pipelines.yml
└── sincedb/

Elastic/Padronizacao_de_Index_Templates_.content:
📌 Contexto
Este documento descreve o problema identificado no cluster Elasticsearch, a solução adotada através de Index Templates, e as remediações aplicadas para controlar o crescimento de shards e estabilizar a alocação no cluster.
O ambiente em questão utiliza:

Kubernetes
Fluentbit/Kafka/Logstash para ingestão de logs
Elasticsearch como datastore
Criação dinâmica de índices por aplicação/container


🚨 Problema Inicial
Cada nova aplicação no cluster Kubernetes que envia logs para o Elasticsearch estava criando novos índices mensais, com a seguinte configuração padrão:

number_of_shards: 3
number_of_replicas: 1

Exemplo de índice criado automaticamente:
{
  &quot;index&quot;: &quot;accounting-api-hub-ctn-2025.12&quot;,
  &quot;number_of_shards&quot;: &quot;3&quot;,
  &quot;number_of_replicas&quot;: &quot;1&quot;
}
Impactos observados

Cada índice consumia 6 shards (3 primários + 3 réplicas)
Crescimento acelerado do número total de shards
Risco de atingir o limite operacional do cluster (~3000 shards)
Problemas de alocação de shards e instabilidade do cluster

A causa raiz identificada foi a existência de index templates específicos por aplicação, que forçavam a criação de índices com 3 shards.
Pipeline do Logstash
input {
    kafka {
        bootstrap_servers =&gt; &quot;${KAFKA_BOOTSTRAP_SERVERS}&quot;
        topics =&gt; [ &quot;${KAFKA_TOPIC}&quot; ]
        security_protocol =&gt; &quot;SASL_SSL&quot;
        sasl_mechanism =&gt; &quot;SCRAM-SHA-512&quot;
        sasl_jaas_config =&gt; &#039;org.apache.kafka.common.security.scram.ScramLoginModule required username=&quot;${KAFKA_USER}&quot; password=&quot;${KAFKA_USER_PASSWORD}&quot;;&#039;
        auto_offset_reset =&gt; &quot;earliest&quot;
        consumer_threads =&gt; &quot;${KAFKA_CONSUMER_THREADS}&quot;
        group_id =&gt; &quot;${GROUP_ID}&quot;
    }
}

filter {
		# Converte o campo `message` (string) em um objeto JSON.
		# Os campos do JSON passam a existir no evento.

    json { source =&gt; &quot;message&quot; }

		# Normalização do campo de log
		# Se existir `logprocessed`, ele vira `log`.
		# Caso contrário, o campo `log` original é renomeado para `raw_log`.
		# Isso diferencia **logs já processados** de **logs crus**.

    if ([logprocessed]) {
        mutate { rename =&gt; [&quot;logprocessed&quot; , &quot;log&quot;] }
    } else {
        mutate { rename =&gt; [&quot;log&quot; , &quot;raw_log&quot;] }
    }

		# Definição do timestamp do evento
		# Define o `@timestamp` do evento com base em vários campos possíveis.
		# Prioriza timestamps vindos do próprio log.
		# Usa `docker_time` como fallback.
		# Se nada existir, mantém o `@timestamp` padrão.

    if ([log][timestamp]) {
        date { match =&gt; [ &quot;[log][timestamp]&quot;, &quot;ISO8601&quot; ] }
    } else if ([log][EventTimeIso8601]) {
        date { match =&gt; [ &quot;[log][EventTimeIso8601]&quot;, &quot;ISO8601&quot; ] }
    } else if ([log][time]) {
        date { match =&gt; [ &quot;[log][time]&quot;, &quot;ISO8601&quot; ] }
    } else if ([docker_time]){
        date { match =&gt; [ &quot;[docker_time]&quot;, &quot;ISO8601&quot; ] }
    } else {
        date { match =&gt; [ &quot;[@timestamp]&quot;, &quot;ISO8601&quot; ] }
    }

    mutate {
        remove_field =&gt; [
            &quot;[log][timestamp]&quot;,
            &quot;[log][EventTimeIso8601]&quot;,
            &quot;[log][time]&quot;,
            &quot;[docker_time]&quot;
        ]

        # Metadados de indexação (default)
        # Define **prefixo do índice** padrão.
        # Define **frequência mensal** por padrão.
        # Esses campos ficam em `@metadata` (não são enviados ao Elasticsearch).

        add_field =&gt; {
            &quot;[@metadata][IndexPrefix]&quot;    =&gt; &quot;logstash&quot;
            &quot;[@metadata][IndexFrequency]&quot; =&gt; &quot;monthly&quot;
        }
    }

    # Tratamento específico de Kubernetes
    if ([kubernetes]) {
        mutate {
		        # Prefixo do índice baseado no container
		        # Cada container pode gerar seu próprio índice.
            update       =&gt; {
                &quot;[@metadata][IndexPrefix]&quot;    =&gt; &quot;%{[kubernetes][container_name]}&quot;
            }
        }

				# Override via label Kubernetes
				# Se existir essa label no pod, ela **define explicitamente o índice.
				# Dá controle total via manifest do Kubernetes.

        if ([kubernetes][labels][acqio.logstash.elastic.co/IndexPrefix] and
            [kubernetes][labels][acqio.logstash.elastic.co/IndexPrefix] != &quot;&quot;) {
            mutate {
                update =&gt; {
                    &quot;[@metadata][IndexPrefix]&quot; =&gt; &quot;%{[kubernetes][labels][acqio.logstash.elastic.co/IndexPrefix]}&quot;
                }
            }
        }

        mutate {
            update =&gt; {
                &quot;[kubernetes][container_image]&quot; =&gt; &quot;%{[kubernetes][container_hash]}&quot;
            }
            remove_field =&gt; [
                &quot;[kubernetes][annotations]&quot;,
                &quot;[kubernetes][container_hash]&quot;,
                &quot;[kubernetes][docker_id]&quot;,
                &quot;[kubernetes][labels][controller-uid]&quot;,
                &quot;[kubernetes][labels][job-name]&quot;,
                &quot;[kubernetes][labels][pod-template-hash]&quot;,
                &quot;[kubernetes][labels][security.istio.io/tlsMode]&quot;,
                &quot;[kubernetes][labels][service.istio.io/canonical-name]&quot;,
                &quot;[kubernetes][labels][service.istio.io/canonical-revision]&quot;,
                &quot;[kubernetes][pod_id]&quot;
            ]
        }
    }

    # Tratamento do conteúdo da mensagem
    # Padroniza tudo para `log.message`.
    if ([log][message] or [log][Message]) {
        if ([log][Message]) {
            mutate {
                copy          =&gt; { &quot;[log][Message]&quot; =&gt; &quot;[log][message]&quot; }
                remove_field  =&gt; [ &quot;[log][Message]&quot; ]
            }
        }

				# Evita erro quando `message` é um objeto JSON.
        ruby {
            code =&gt; &#039;
                if not event.get(&quot;[log][message]&quot;).is_a? String
                    event.set(&quot;[log][message]&quot;, event.get(&quot;[log][message]&quot;).to_json)
                end
            &#039;
        }
    }

	# Se `log.message` for JSON válido:
		# Ele é parseado para `log.record`
		# O campo `log.message` é removido
	# Diferencia **mensagem textual** de **mensagem estruturada.

    if [log][message] {
       json {
           source =&gt; &quot;[log][message]&quot;
           target =&gt; &quot;[log][record]&quot;
           skip_on_invalid_json =&gt; &quot;true&quot;
       }
   }
	  if [log][record] {
       mutate {
           remove_field =&gt; [ &quot;[log][message]&quot; ]
       }
	  }

	# Tratamento especial para métricas
	# Logs e métricas ficam **separados em índices diferentes.

    if ([log][metric][@name] and [log][metric][@name] != &quot;&quot;) {
        mutate {
            update      =&gt; {
                &quot;[@metadata][IndexPrefix]&quot;    =&gt; &quot;metric-%{[log][metric][@name]}&quot;
                &quot;[@metadata][IndexFrequency]&quot; =&gt; &quot;monthly&quot;
            }
        }

        if ([log][metric][@metadata][idx_split]) {
            mutate {
                update       =&gt; {
                    &quot;[@metadata][IndexFrequency]&quot; =&gt; &quot;%{[log][metric][@metadata][idx_split]}&quot;
                }
                remove_field =&gt; [ &quot;[log][metric][@metadata]&quot; ]
            }
        }
        mutate {
            rename =&gt; [ &quot;[log][metric]&quot;, &quot;[metric]&quot; ]
        }
    }

    # Definição final do nome do índice
    # Exemplo de formatos:
	    # Daily: `app-2026.01.05`
	    # Monthly: `app-2026.01`
	    # Yearly: `app-2026`

	# O nome do índice é **dinâmico**.
	# Baseado em:
		# Container
		# Label Kubernetes
		# Tipo de dado (log ou métrica)
		# Frequência temporal

    mutate { lowercase =&gt; [ &quot;[@metadata][IndexPrefix]&quot;, &quot;[@metadata][IndexFrequency]&quot; ] }
    mutate { replace =&gt; { &quot;[@metadata][IndexDateFormat]&quot; =&gt; &quot;%{+YYYY.MM}&quot; } }

    if [@metadata][IndexFrequency] == &quot;daily&quot; {
        mutate { replace =&gt; { &quot;[@metadata][IndexDateFormat]&quot; =&gt; &quot;%{+YYYY.MM.dd}&quot; } }
    } else if [@metadata][IndexFrequency] == &quot;monthly&quot; {
        mutate { replace =&gt; { &quot;[@metadata][IndexDateFormat]&quot; =&gt; &quot;%{+YYYY.MM}&quot; } }
    } else if [@metadata][IndexFrequency] == &quot;yearly&quot; {
        mutate { replace =&gt; { &quot;[@metadata][IndexDateFormat]&quot; =&gt; &quot;%{+YYYY}&quot; } }
    } else {
        mutate { replace =&gt; { &quot;[@metadata][IndexDateFormat]&quot; =&gt; &quot;%{+xxxx.ww}&quot; } }
    }

    mutate {
        add_field    =&gt; { &quot;[@metadata][IndexName]&quot; =&gt; &quot;%{[@metadata][IndexPrefix]}-%{[@metadata][IndexDateFormat]}&quot; }
        remove_field =&gt; [ &quot;message&quot; ]
    }
}

output {
    elasticsearch {
        hosts =&gt; [ &quot;${ELASTICSEARCH_HOST}&quot; ]
        ssl =&gt; true
        index =&gt; &quot;%{[@metadata][IndexName]}&quot;
        user =&gt; &quot;${ELASTICSEARCH_USER}&quot;
        password =&gt; &quot;${ELASTICSEARCH_PASSWORD}&quot;
    }
}
Como funcionam os Index Template
Conceito
Index Templates são aplicados somente no momento da criação do índice
Eles definem:

Settings (shards, replicas, ILM, etc.)
Mappings
Aliases

Após o índice ser criado:

Não existe vínculo persistente entre o índice e o template
As configurações são apenas copiadas para o índice

Resolução de conflitos
Quando múltiplos templates combinam com o nome de um índice:

Todos os templates compatíveis são avaliados
O template com maior priority é aplicado
Não há merge de number_of_shards

🛠️ Solução Implementada
Foi criado um Index Template global para logs Kubernetes, com prioridade maior que os templates existentes.
Template aplicado
PUT _index_template/logstash-kubernetes-logs-template
{
  &quot;index_patterns&quot;: [&quot;*-ctn-20*.*&quot;],
  &quot;priority&quot;: 700,
  &quot;template&quot;: {
    &quot;settings&quot;: {
      &quot;number_of_shards&quot;: 1,
      &quot;number_of_replicas&quot;: 1,
      &quot;index.lifecycle.name&quot;: &quot;expire_index_after_30d&quot;
    }
  }
}
Resultado
Novos índices passam a ser criados com:

✅ 1 shard primário
✅ 1 réplica
Redução imediata de ~66% no consumo de shards por índice
Nenhum impacto em índices já existentes
Compatível com políticas de ILM já em uso

🔎 Validação e Evidências
Simulação oficial do Elasticsearch
POST _index_template/_simulate_index/meu-custom-index-ctn-2026.12
A resposta confirma:

O template aplicado
A prioridade vencedora
Os settings finais do índice


⚠️ O Elasticsearch não mantém referência ao template após a criação do índice.
A simulação é a evidência oficial do mecanismo de decisão.

Validação do índice criado
PUT meu-custom-index-ctn-2026.12
GET meu-custom-index-ctn-2026.12/_settings
{
  &quot;meu-custom-index-ctn-2026.12&quot;: {
    &quot;settings&quot;: {
      &quot;index&quot;: {
        &quot;lifecycle&quot;: {
          &quot;name&quot;: &quot;expire_index_after_30d&quot;
        },
        &quot;routing&quot;: {
          &quot;allocation&quot;: {
            &quot;include&quot;: {
              &quot;_tier_preference&quot;: &quot;data_content&quot;
            }
          }
        },
        &quot;number_of_shards&quot;: &quot;1&quot;,
        &quot;provided_name&quot;: &quot;meu-custom-index-ctn-2026.12&quot;,
        &quot;creation_date&quot;: &quot;1767879001169&quot;,
        &quot;priority&quot;: &quot;100&quot;,
        &quot;number_of_replicas&quot;: &quot;1&quot;,
        &quot;uuid&quot;: &quot;J614BOqkQm20EtCVKpn8oQ&quot;,
        &quot;version&quot;: {
          &quot;created&quot;: &quot;8500003&quot;
        }
      }
    }
  }
}
🧹 Remediações Aplicadas
Curto prazo

Criação de template com prioridade maior
Correção automática do número de shards para novos índices

Médio prazo (recomendado)

Revisar e consolidar templates específicos por aplicação
Evitar criação automática de templates por app/container
Centralizar templates por tipo de dado (logs, métricas)

Boas práticas adotadas

Controle de shards via Index Template
Uso de ILM para retenção automática
Separação clara de responsabilidades:

Logstash → ingestão
Elasticsearch → governança de índices

